package sessionpg

import (
	"bytes"
	"github.com/MiniMax-AI/OpenAgentCore/services/core/internal/credentialcrypto"
	"testing"
)

func TestDurableProviderKeyFingerprint(t *testing.T) {
	c, err := credentialcrypto.New(bytes.Repeat([]byte{7}, 32))
	if err != nil {
		t.Fatal(err)
	}
	got, err := (&Store{cipher: c}).FingerprintProviderKey("public-fixture-key")
	// Fixed public fixture generated by source 4b16ddbbfe5ad5984547e54d60bb9a89c7c79d81.
	if err != nil || got != "09a28bdd93e9fdcdc5fc09d4fea1c0cf4d75adf1bdf04f08e9678e1fd0e45304" {
		t.Fatal("persisted request identity changed")
	}
}

func TestDurableInstallationSignature(t *testing.T) {
	c, err := credentialcrypto.New(bytes.Repeat([]byte{7}, 32))
	if err != nil {
		t.Fatal(err)
	}
	s := &Store{cipher: c}
	got, err := s.installationSignature("public-fixture-authorization")
	if err != nil || got != "f7be23c8bf606c87300aa7c3c6087b3639a63dab8c8d682af220e0747a1f90fc" {
		t.Fatal("installation authorization signature changed")
	}
	if err := s.VerifyInstallation(t.Context(), "public-fixture-authorization", got); err != nil {
		t.Fatal("stored authorization rejected")
	}
	if err := s.VerifyInstallation(t.Context(), "another-authorization", got); err == nil {
		t.Fatal("signature accepted changed payload")
	}
}
